using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 stores the discriminator as "$type" instead of "Discriminator".
            // Existing 500K docs use "Discriminator", and direct SQL queries reference
            // c.Discriminator, so we keep the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id format simplified.
            // EF Core 8 wrote id as "Product|123"; EF Core 9 writes just "123".
            // Map an explicit CosmosId property so existing docs are still found.
            entity.Property(p => p.CosmosId).ToJsonProperty("id");
            entity.HasKey(p => p.Id);

            // BREAKING CHANGE 3 — HasIndex() on Cosmos now throws.
            // Cosmos DB doesn't support EF-managed indexes; the previous
            // HasIndex(p => p.Sku) call has been removed.
            // Manage indexes in the Azure Portal or via IaC instead.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // BREAKING CHANGE 4 — Sync APIs removed.
        // EF Core 9 Cosmos provider no longer supports synchronous queries.
        // Suppress the warning while migrating callers to async.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CoreEventId.SyncAndAsyncNotSupported));

        base.OnConfiguring(optionsBuilder);
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }

    // Preserves EF Core 8 id format ("Product|{Id}") so existing documents
    // in Cosmos DB are still addressable by key.
    public string CosmosId
    {
        get => $"Product|{Id}";
        private set { }        // setter required for materialization
    }
}

